KG42.register("rules-1478d8bc637140c57938d114",{"id":"26-battery_flexibility::v141-c-R002","paper":"26-battery_flexibility","record":{"rule_id":"v141-c-R002","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"The dynamic local P2P price is applied as each house's purchase price for P2P exchanges. Scope: Flexi User P2P electricity purchases within the community; house-specific dynamic purchase prices. Peers may sell excess electricity from locally generated renewable energy to other peers within the community. Scope: Flexi User peer exchanges within the community. P2P sales and purchases remain within the community under the design's exclusion of grid feed-in. Scope: Flexi User P2P sales and purchases. Each house's total P2P sales and purchases aggregate bilateral flows with other peers. Bilateral purchases equal the corresponding reverse-direction sales adjusted by the distribution-loss and DG-conversion factor; total community purchases must likewise equal adjusted community sales. Scope: Modeled Flexi User P2P exchanges among community houses at each time step; bilateral flows concern distinct houses.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["execution.energy_trade","pricing.local"],"E":[{"edge_id":"v141-c-R002-E001","source":"pricing.local","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R002-C001"],"evidence_ids":["v141-b-g01-e01","v141-b-g02-e16"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Flexi User P2P electricity purchases within the community; house-specific dynamic purchase prices. | Flexi User P2P sales and purchases. | Flexi User peer exchanges within the community. | Modeled Flexi User P2P exchanges among community houses at each time step; bilateral flows concern distinct houses.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e01","v141-b-g01-e03","v141-b-g01-e06","v141-b-g01-e15","v141-b-g01-e16","v141-b-g01-e17","v141-b-g01-e18","v141-b-g02-e16"]},"x":[{"variable_id":"v141-c-R002-X001","symbol":"X^{(t,h)}","meaning":"P2P electricity sale of house h in time step t, aggregated over peers p != h.","kind":"operational","domain":"Unspecified energy quantity indexed by t in T and h in H; the quoted source definition does not state nonnegativity.","unit":null,"indices":["t","h"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e15"]},{"variable_id":"v141-c-R002-X002","symbol":"X^{p}(t,h\\rightarrow p)","meaning":"P2P electricity sale of house h to peer p in time step t.","kind":"operational","domain":"Unspecified energy flow indexed by t in T and h,p in H with p != h in Eqs. (2)-(3); the quoted source definition does not state nonnegativity.","unit":null,"indices":["t","h","p"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e15","v141-b-g01-e16"]},{"variable_id":"v141-c-R002-X003","symbol":"I^{(t,h)}","meaning":"P2P electricity purchase of house h in time step t, aggregated over peers p != h.","kind":"operational","domain":"Unspecified energy quantity indexed by t in T and h in H; the quoted source definition does not state nonnegativity.","unit":null,"indices":["t","h"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e17"]},{"variable_id":"v141-c-R002-X004","symbol":"I^{p}(t,h\\leftarrow p)","meaning":"P2P electricity purchase of house h from peer p in time step t.","kind":"operational","domain":"Unspecified energy flow indexed by t in T and h,p in H with p != h; the quoted source definition does not state nonnegativity.","unit":null,"indices":["t","h","p"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e16","v141-b-g01-e17"]}],"theta":[{"parameter_id":"v141-c-R002-P001","symbol":"p_{p2p}^{(t,h)}","meaning":"Price of electricity in the local market for house h in time step t; the dynamic local P2P purchase price applied to house h's P2P exchanges.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t","h"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e01","v141-b-g02-e16"]},{"parameter_id":"v141-c-R002-P002","symbol":"\\psi^{P2P}","meaning":"Distribution network losses and conversion of DG for P2P sale; the multiplicative factor relating a peer sale flow to the corresponding purchase flow.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e16","v141-b-g01-e18"]}],"phi":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"The dynamic local P2P price is applied as each house's purchase price for P2P exchanges. Scope: Flexi User P2P electricity purchases within the community; house-specific dynamic purchase prices.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","execution.energy_trade"],"variable_refs":[],"parameter_refs":["v141-c-R002-P001"],"evidence_ids":["v141-b-g01-e01","v141-b-g02-e16","v141-b-g01-e06"]},{"constraint_id":"v141-c-R002-C002","kind":"procedural","role":"core","statement":"Peers may sell excess electricity from locally generated renewable energy to other peers within the community. Scope: Flexi User peer exchanges within the community.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e03"]},{"constraint_id":"v141-c-R002-C003","kind":"procedural","role":"core","statement":"P2P sales and purchases remain within the community under the design's exclusion of grid feed-in. Scope: Flexi User P2P sales and purchases.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e18"]},{"constraint_id":"v141-c-R002-C004","kind":"mathematical","role":"core","statement":"Each house's total P2P sales and purchases aggregate bilateral flows with other peers. Bilateral purchases equal the corresponding reverse-direction sales adjusted by the distribution-loss and DG-conversion factor; total community purchases must likewise equal adjusted community sales. Scope: Modeled Flexi User P2P exchanges among community houses at each time step; bilateral flows concern distinct houses.","expression":"\\begin{aligned} X^{(t,h)} &= \\sum_{p \\ne h} X^{p}(t,h\\rightarrow p), && \\forall t\\in T,\\, h\\in H; \\\\ I^{p}(t,h\\leftarrow p) &= \\psi^{P2P}\\cdot X^{p}(t,p\\rightarrow h), && \\forall t\\in T,\\, h,p\\in H,\\, p\\ne h; \\\\ I^{(t,h)} &= \\sum_{p \\ne h} I^{p}(t,h\\leftarrow p), && \\forall t\\in T,\\, h\\in H; \\\\ \\sum_h \\psi^{P2P}\\cdot X^{(t,h)} &= \\sum_h I^{(t,h)}, && \\forall t\\in T. \\end{aligned}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R002-X001","v141-c-R002-X002","v141-c-R002-X003","v141-c-R002-X004"],"parameter_refs":["v141-c-R002-P002"],"evidence_ids":["v141-b-g01-e06","v141-b-g01-e15","v141-b-g01-e16","v141-b-g01-e17","v141-b-g01-e18","v141-b-g01-e14","v141-b-g02-e10"]}],"pi":[{"evidence_id":"v141-b-g01-e01","location":{"location_id":"src-9788b5496d-p04-c2r3__v141-a-M01-participation","page":4,"printed_page":null,"section":"3.1 Market design for peer-to-peer trading","anchor_text":"he ability to sell excess electricity from renewable energy sources to peers. Each of the two setups","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Decentralised storage – Flexi User Market: This market design applies rules to the system setup with individually owned batteries. Prosumers and consumers within a community can trade locally produced energy at a dynamic local P2P price. Privately owned storage can be charged by DG from prosumers within the community."},{"evidence_id":"v141-b-g01-e03","location":{"location_id":"src-9788b5496d-p04-c2r2__v141-a-M01-participation","page":4,"printed_page":null,"section":"3.1 Market design for peer-to-peer trading","anchor_text":"nt setups: decentralised (a) versus centralised battery (b). of market and steers its actions [39]. ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Fig. 2 shows the setups underlying the two distinct market designs. The Flexi User is designed for a setting with individual batteries at consumer level. Then, the structure in the Pool Hub considers a large battery at the community level. For both designs, we allow the trade of locally generated electricity within the community, where trade is the ability to sell excess electricity from renewable energy sources to peers. Each of the two setups gives the storage entity a certain role leading to the following distinct market design definitions:"},{"evidence_id":"v141-b-g01-e06","location":{"location_id":"src-9788b5496d-p04-c1r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"Table 1","anchor_text":"dem(t , h ) Demand of house h in time step t res (t , h ) Renewable energy production of house h in ","equation_id":null,"figure_id":null,"table_id":"Table 1","image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Table 1. Designated sets, parameters and variables of the mathematical model. Sets: t ∈ T — Hours t in time horizon T; h, p ∈ H — Houses h and peers p in community H. Scalars: \\psi^{P2P} — Distribution network losses and conversion of DG for P2P sale; \\underline{s}/\\bar{s} — Upper/lower bounds of storage level in battery; \\alpha/\\beta — Maximum charge/discharge rate of battery; \\eta^c/\\eta^d — Battery charging/discharging efficiency. Parameters: dem^{(t,h)} — Demand of house h in time step t; res^{(t,h)} — Renewable energy production of house h in time step t; p_G^{(t)} — Price of electricity from the grid in time step t; p_{p2p}^{(t,h)} — Price of electricity in the local market for house h in time step t; p_C^{(t)} — Price of charging the common battery in time step t; p_D^{(t,h)} — Price of discharging the common battery in time step t. Variables: C^{(t,h)} — Charge of battery of house h in time step t; D^{(t,h)} — Discharge of battery of house h in time step t; G^{(t,h)} — Grid consumption of house h in time step t; I^{(t,h)} — P2P electricity purchase of house h in time step t; I^{p}(t,h\\leftarrow p) — P2P electricity purchase of house h from peer p in time step t; S^{(t,h)} — Energy storage level in battery of house h in time step t; X^{(t,h)} — P2P electricity sale of house h in time step t; X^{p}(t,h\\rightarrow p) — P2P electricity sale of house h to peer p in time step t."},{"evidence_id":"v141-b-g01-e15","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":"(2)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The community is interconnected to allow prosumers a direct trade of electricity with their fellow peers. Enabled trade needs to follow certain rules. The overall sales quantity X^{(t,h)} for each house h \\in H is defined as the sum of all electricity flows X^{p}(t,h\\rightarrow p) from this house h \\in H to its peers p \\in H, Eq. (2). X^{(t,h)} = \\sum_{p \\ne h} X^{p}(t,h\\rightarrow p) (2)."},{"evidence_id":"v141-b-g01-e16","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":"(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Given that I^{p}(t,h\\leftarrow p) = \\psi^{P2P} \\cdot X^{p}(t,p\\rightarrow h) \\; \\forall p \\ne h, (3) the change of the flow direction indicates a purchase I^{p}(t,h\\leftarrow p) of one house h \\in H from its peer p \\in H."},{"evidence_id":"v141-b-g01-e17","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":"(4)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The overall purchased quantity per house, I^{(t,h)}, is then specified by Eq. (4). I^{(t,h)} = \\sum_{p \\ne h} I^{p}(t,h\\leftarrow p) (4)."},{"evidence_id":"v141-b-g01-e18","location":{"location_id":"src-9788b5496d-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the co","equation_id":"(5)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the community. The sum of sales over all houses needs to equal the purchases as follows with Eq. (5). \\sum_h \\psi^{P2P} \\cdot X^{(t,h)} = \\sum_h I^{(t,h)} \\; \\forall t \\in T. (5)"},{"evidence_id":"v141-b-g02-e16","location":{"location_id":"src-9788b5496d-p07-c1r3__v141-a-M01-pricing","page":7,"printed_page":null,"section":"4.1.4 Electricity prices","anchor_text":"Fig. 3. Demand cover for exemplary houses on a scaled up to represent typical price levels customers","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"A reasonable price for P2P trade should reflect the willingness of each prosumer to pay for an extra unit of electricity under the assumption that there is no possibility for local trade or storage. The shadow price of each single prosumer can be seen as the willingness to pay of each prosumer. This approach is analogous to the proposition of Abbaspourtorbati et al. [45] who calculated clearing prices by the dual variables of the energy balance equations. To calculate the P2P prices, we independently minimise each prosumer’s costs for electricity subject to the supply-demand balance in Eq. (1) in the absence of storage and interconnection. The result of the separate optimisations provides a dynamic willingness to pay for electricity of each house in each time step. Since this P2P price should not consider the fees for network and grid usage (typically one third of the consumer bill, see [46]), we downscaled these prices by 36% as we assume that grid usage costs do not occur when electricity is traded locally in the community. Reflecting the willingness to pay for electricity, we implement these downscaled shadow prices as the house’s purchase price for P2P trade."},{"evidence_id":"v141-b-g01-e14","location":{"location_id":"src-9788b5496d-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2 Model formulation","anchor_text":"have the supply greater equal to demand by Eq. (1)4: 0 RES + Grid+ Battery discharge+ ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"All equations hold true for all h \\in H, t \\in T."},{"evidence_id":"v141-b-g02-e10","location":{"location_id":"src-9788b5496d-p05-c2r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.2.1 Peer-to-peer trade","anchor_text":"Applied Energy 229 (2018) 1233–1243 X (t , h ) = ∑ X p(t , h → p ) p ≠ h (2) Given that I p(t , h ← ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The community is interconnected to allow prosumers a direct trade of electricity with their fellow peers. Enabled trade needs to follow certain rules. The overall sales quantity X^{(t,h)} for each house h∈H is defined as the sum of all electricity flows X_p^{(t,h\\rightarrow p)} from this house h∈H to its peers p∈H, Eq. (2). X^{(t,h)} = \\sum_{p \\neq h} X_p^{(t,h\\rightarrow p)} (2). Given that I_p^{(t,h\\leftarrow p)} = \\psi^{P2P} \\cdot X_p^{(t,p\\rightarrow h)} \\quad \\forall p \\neq h, (3), the change of the flow direction indicates a purchase I_p^{(t,h\\leftarrow p)} of one house h∈H from its peer p∈H. The overall purchased quantity per house, I^{(t,h)}, is then specified by Eq. (4). I^{(t,h)} = \\sum_{p \\neq h} I_p^{(t,h\\leftarrow p)} (4). As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the community. The sum of sales over all houses needs to equal the purchases as follows with Eq. (5). \\sum_h \\psi^{P2P} \\cdot X^{(t,h)} = \\sum_h I^{(t,h)} \\quad \\forall t \\in T. (5)"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M02-clearing","v141-a-M02-participation","v141-a-M02-pricing"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e01","quote":"Prosumers and consumers within a community can trade locally produced energy at a dynamic local P2P price."},{"evidence_id":"v141-b-g02-e16","quote":"Reflecting the willingness to pay for electricity, we implement these downscaled shadow prices as the house’s purchase price for P2P trade."}],[{"evidence_id":"v141-b-g01-e03","quote":"For both designs, we allow the trade of locally generated electricity within the community, where trade is the ability to sell excess electricity from renewable energy sources to peers."}],[{"evidence_id":"v141-b-g01-e18","quote":"As no grid feed-in is considered, the sold and purchased quantity can, thus, only stay within the community."}],[{"evidence_id":"v141-b-g01-e15","quote":"The overall sales quantity X^{(t,h)} for each house h \\in H is defined as the sum of all electricity flows X^{p}(t,h\\rightarrow p) from this house h \\in H to its peers p \\in H, Eq. (2). X^{(t,h)} = \\sum_{p \\ne h} X^{p}(t,h\\rightarrow p) (2)."},{"evidence_id":"v141-b-g01-e17","quote":"The overall purchased quantity per house, I^{(t,h)}, is then specified by Eq. (4). I^{(t,h)} = \\sum_{p \\ne h} I^{p}(t,h\\leftarrow p) (4)."},{"evidence_id":"v141-b-g01-e16","quote":"Given that I^{p}(t,h\\leftarrow p) = \\psi^{P2P} \\cdot X^{p}(t,p\\rightarrow h) \\; \\forall p \\ne h, (3) the change of the flow direction indicates a purchase I^{p}(t,h\\leftarrow p) of one house h \\in H from its peer p \\in H."},{"evidence_id":"v141-b-g01-e18","quote":"The sum of sales over all houses needs to equal the purchases as follows with Eq. (5). \\sum_h \\psi^{P2P} \\cdot X^{(t,h)} = \\sum_h I^{(t,h)} \\; \\forall t \\in T. (5)"},{"evidence_id":"v141-b-g01-e06","quote":"\\psi^{P2P} — Distribution network losses and conversion of DG for P2P sale"}]],"C2_formalization":{"graph_sha256":"c3a2c3463581414120f85c834a89b3dc1d6bcf7fa20641b8c858981b39f31a13","applicability":"formalized","reason":"C004 is formalized by faithful transcription of the source P2P trade equations (2)-(5), using declared aggregate and bilateral P2P sale/purchase variables and the P2P loss/conversion factor psi^{P2P}. C001-C003 remain non-formalized procedural or scope statements: C001's source describes application of downscaled shadow prices as purchase prices without giving the exact arithmetic, and C002-C003 state permissions/no-grid-feed-in scope. B evidence is unreviewed in this experiment; this is not a claim of independent source verification.","bindings":[{"object_id":"v141-c-R002-X001","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"X^{(t,h)} is a P2P electricity sale quantity and is defined by Eq. (2) as an execution.energy_trade energy flow. No pricing edge is involved in this quantity definition."},{"object_id":"v141-c-R002-X002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"X^{p}(t,h\\rightarrow p) is a bilateral P2P sale flow from house h to peer p and is an execution.energy_trade quantity in Eqs. (2)-(3)."},{"object_id":"v141-c-R002-X003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"I^{(t,h)} is a P2P electricity purchase quantity and is defined by Eq. (4) as an execution.energy_trade energy flow."},{"object_id":"v141-c-R002-X004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"I^{p}(t,h\\leftarrow p) is a bilateral P2P purchase flow from peer p to house h and is an execution.energy_trade quantity in Eq. (3)."},{"object_id":"v141-c-R002-P001","node_ids":["pricing.local"],"edge_ids":["v141-c-R002-E001"],"rationale":"p_{p2p}^{(t,h)} is the local market price parameter under pricing.local. The frozen edge E001 is the rule's link by which C001 applies this local price to execution.energy_trade."},{"object_id":"v141-c-R002-P002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"psi^{P2P} is the distribution-loss/DG-conversion factor appearing in the P2P trade equations (2)-(5); those are execution.energy_trade quantity relations and do not use the pricing edge."},{"object_id":"v141-c-R002-C004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The formalized equations (2)-(5) define aggregate and bilateral P2P sale/purchase quantities and the community P2P balance. They are execution.energy_trade relations; the pricing.local edge E001 is not part of these quantity equations."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"a078a19a2ed27b58d6766d60e19fae24f4dcc4c4f5f9630f2a4b3a3e028c73a4","delivery_payload_sha256":"951ba042f00de061f8141a32a0246061dea70eb2c65c6686a83b7295545dd3e3","changes":[{"path":"theta.0.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."},{"path":"theta.1.value.kind","before":"symbolic","after":"unspecified","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"c3a2c3463581414120f85c834a89b3dc1d6bcf7fa20641b8c858981b39f31a13","scientific_correctness_verified":false}},"quarantined_references":[]}});
